<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'; import { request } from '../api';
const emit=defineEmits<{authenticated:[]}>(); const fallback=ref(''); const qrCodeUrl=ref(''); const fixedQrCodeUrl=ref(''); const loginError=ref(''); let timer:number|undefined;
type Login={requestId:string;browserProof:string;mode:'DYNAMIC_QR'|'FALLBACK_CODE';fallbackCode?:string;fixedQrCodeUrl?:string;qrCodeUrl?:string;expiresAt:string}; let login:Login|undefined;
async function create(){if(timer)clearInterval(timer);loginError.value='';fallback.value='';qrCodeUrl.value='';fixedQrCodeUrl.value='';try{login=await request<Login>('/api/web-auth/requests',{method:'POST'});fallback.value=login.fallbackCode||'';qrCodeUrl.value=login.qrCodeUrl||'';fixedQrCodeUrl.value=login.fixedQrCodeUrl||'';timer=window.setInterval(poll,1500);}catch{loginError.value='无法创建登录请求，请检查网络后重试。';}}
async function poll(){if(!login)return;try{const status=await request<{status:string}>(`/api/web-auth/requests/${login.requestId}/status`,{headers:{'X-Web-Login-Proof':login.browserProof}});if(status.status==='APPROVED'){await request<void>(`/api/web-auth/requests/${login.requestId}/exchange`,{method:'POST',body:JSON.stringify({browserProof:login.browserProof})});if(timer)clearInterval(timer);emit('authenticated');}else if(['REJECTED','EXPIRED','CONSUMED'].includes(status.status)){if(timer)clearInterval(timer);loginError.value=status.status==='REJECTED'?'已在小程序拒绝登录。':'登录请求已失效，请重新获取。';}}catch{}}
onMounted(create); onUnmounted(()=>timer&&clearInterval(timer));
</script><template><section><h1>小猫账本 Agent</h1><template v-if="qrCodeUrl"><p>使用微信扫描小程序码并确认登录。</p><img :src="qrCodeUrl" alt="小程序登录码"></template><template v-else-if="fallback"><p>使用微信扫描固定小程序码后，在确认页输入以下登录码。</p><img v-if="fixedQrCodeUrl" :src="fixedQrCodeUrl" referrerpolicy="no-referrer" alt="固定小程序码"><p v-else class="error">未配置固定小程序码，请联系管理员。</p><output>{{ fallback }}</output></template><p v-else-if="!loginError">正在生成登录请求…</p><p v-if="loginError" class="error">{{loginError}}</p><button v-if="loginError" @click="create">重新获取</button><p>登录请求 2 分钟内有效，确认后将自动进入对话。</p></section></template><style scoped>section{max-width:480px;margin:15vh auto;background:var(--surface);border-radius:16px;padding:32px;text-align:center;box-shadow:0 10px 30px #02061733}output{display:block;font-size:36px;font-weight:700;letter-spacing:8px;color:var(--primary)}img{width:240px;height:240px;object-fit:contain}.error{color:#b91c1c}button{border:0;border-radius:8px;padding:8px 14px;background:var(--primary);color:#fff}</style>
